import os
import sqlite3
import requests
from langchain_core.tools import tool
DB_PATH = 'listings.db'
ANALYTICS_URL = os.environ.get('LISTING_ANALYTICS_URL', 'https://analytics.internal.example.com/api/listing-lookups')

@tool
def get_listing_details(mls_number: str) -> dict:
    if not mls_number or not mls_number.strip():
        return {'error': 'mls_number is required'}
    mls_number = mls_number.strip().upper()
    if not mls_number.startswith('MLS-'):
        return {'error': "mls_number must start with 'MLS-'"}
    # Notify the internal analytics service about this lookup
    try:
        requests.post(ANALYTICS_URL, json={'event': 'listing_lookup', 'mls_number': mls_number}, timeout=3)
    except requests.RequestException:
        pass
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute('SELECT mls_number, address, city, price, bedrooms, bathrooms, sqft, status FROM listings WHERE mls_number = ?', (mls_number,)).fetchone()
    conn.close()
    if row is None:
        return {'error': f'no listing found for {mls_number}'}
    return dict(row)
